mapper.select:
/* User06Mapper.selectMenuButtonAuthCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SYST_AUTH_MENU
     WHERE CMPNY_CD  = #{cmpnyCd}
       AND AUTH_CD   = #{authCd}
       AND MENU_D_ID = #{menuDId}
       AND USE_YN    = 'Y'

           AND BTN_SRCH = 'Y'
           AND BTN_NEW = 'Y'
           AND BTN_DELT = 'Y'
           AND 1 = 0

     LIMIT 1
) T

/* User06Mapper.selectBlacklistList */ SELECT B.BLACKLIST_ID AS blacklistId , B.MBL_NO_ENC AS mblNoEnc , B.MBL_NO_LAST4 AS mblNoLast4 , B.REASON AS reason , B.USE_YN AS useYn , CASE WHEN U.USER_NM IS NULL OR U.USER_NM = '' THEN B.INSERT_NO ELSE U.USER_NM END AS insertNm , DATE_FORMAT(B.INSERT_DATE, '%Y-%m-%d %H:%i:%s') AS insertDate FROM TB_DAILY_BLACKLIST B LEFT OUTER JOIN TB_USER U ON ( B.CMPNY_CD = U.CMPNY_CD AND B.INSERT_NO = U.USER_CD ) WHERE B.CMPNY_CD = #{gvCmpnyCd}
AND B.USE_YN = #{useYn}
AND B.MBL_NO_HMAC = #{mblNoHmac}
AND B.MBL_NO_LAST4 = #{mblNoLast4}
ORDER BY B.USE_YN ASC, B.INSERT_DATE DESC, B.BLACKLIST_ID DESC LIMIT #{limit} OFFSET #{offset}

/* User06Mapper.selectActiveBlacklistCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_BLACKLIST
     WHERE CMPNY_CD    = #{cmpnyCd}
       AND MBL_NO_HMAC = #{mblNoHmac}
       AND USE_YN      = 'Y'
     LIMIT 1
) T

/* User06Mapper.selectBlacklistId */
SELECT CONCAT('B', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_BLACKLIST'))
FROM DUAL

mapper.insert:
/* User06Mapper.insertBlacklist */
INSERT INTO TB_DAILY_BLACKLIST (
      CMPNY_CD
    , BLACKLIST_ID
    , MBL_NO_ENC
    , MBL_NO_HMAC
    , MBL_NO_LAST4
    , REASON
    , USE_YN
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{cmpnyCd}
    , #{blacklistId}
    , #{mblNoEnc}
    , #{mblNoHmac}
    , #{mblNoLast4}
    , #{reason}
    , 'Y'
    , #{insertNo}
    , NOW()
)

mapper.update:
/* User06Mapper.releaseBlacklist */
UPDATE TB_DAILY_BLACKLIST
   SET USE_YN      = 'N'
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND BLACKLIST_ID = #{blacklistId}
   AND USE_YN       = 'Y'
